import React from 'react';
import { Link } from 'react-router-dom';

const Navbar = () => {
  return (
    <nav className="bg-white shadow-md">
      <div className="container mx-auto px-4">
        <div className="flex justify-between items-center py-4">
          {/* Logo */}
          <Link to="/" className="flex items-center space-x-2">
            <span className="text-2xl font-bold text-blue-600">🚗 RentCar</span>
          </Link>

          {/* Menü */}
          <div className="space-x-6">
            <Link to="/" className="text-gray-700 hover:text-blue-600 font-medium">Anasayfa</Link>
            <Link to="/arac-kontrol" className="text-gray-700 hover:text-blue-600 font-medium">Araç Kontrol</Link>
            <Link to="/login" className="text-gray-700 hover:text-blue-600 font-medium">Giriş Yap</Link>
            <Link to="/mobiliz" className="text-gray-700 hover:text-blue-600 font-medium">Mobiliz</Link>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
